hold_ticks := 0
if ((#Office_Plug).plug_power < 5) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 600) {
n := 0
        if (n >= 3) {
break
}
(#Office_Speaker).speaker_speak("Device is idle")
        n = n + 1
}
}
else {
hold_ticks = 0
}

